const leads = $('Sheets — Leer RAW_LEADS').all();
const today = new Date();

// --- CVR leads ---
const cvr = leads.filter(i => i.json.Fuente === 'cvr');
const cvrTotal = cvr.length;
const cvrEmail = cvr.filter(i => (i.json.Email || '').includes('@')).length;
const cvrNuevo = cvr.filter(i => i.json.Estado === 'nuevo').length;
const cvrEmailed = cvr.filter(i => i.json.Estado === 'emailed').length;

// --- By sector (Industry field from CVR branche) ---
const sectors = {};
for (const lead of cvr) {
  const raw = (lead.json.Industry || 'sin sector').trim();
  const sector = raw.length > 30 ? raw.substring(0, 27) + '...' : raw;
  if (!sectors[sector]) sectors[sector] = { total: 0, email: 0, nuevo: 0, emailed: 0 };
  sectors[sector].total++;
  if ((lead.json.Email || '').includes('@')) sectors[sector].email++;
  if (lead.json.Estado === 'nuevo') sectors[sector].nuevo++;
  if (lead.json.Estado === 'emailed') sectors[sector].emailed++;
}

const sorted = Object.entries(sectors).sort((a, b) => b[1].total - a[1].total);
let sectorLines = '';
for (const [name, s] of sorted) {
  sectorLines += `  ${name}: ${s.total} (email ${s.email} | sent ${s.emailed})\n`;
}

// --- WF7 Cold Email Stats ---
const cvrConEmailNuevo = cvr.filter(i => (i.json.Email || '').includes('@') && i.json.Estado === 'nuevo').length;
const emailRate = cvrTotal > 0 ? Math.round(cvrEmail / cvrTotal * 100) : 0;
const sendRate = cvrEmail > 0 ? Math.round(cvrEmailed / cvrEmail * 100) : 0;

// Sector breakdown for emailed
const emailedBySector = {};
for (const lead of cvr) {
  if (lead.json.Estado !== 'emailed') continue;
  const raw = (lead.json.Industry || 'sin sector').trim();
  const sector = raw.length > 25 ? raw.substring(0, 22) + '...' : raw;
  emailedBySector[sector] = (emailedBySector[sector] || 0) + 1;
}
const emailedSectorLines = Object.entries(emailedBySector)
  .sort((a, b) => b[1] - a[1])
  .map(([name, count]) => `  ${name}: ${count} sent`)
  .join('\n');

// --- Other sources in RAW_LEADS ---
const otherCounts = {};
for (const lead of leads) {
  const src = lead.json.Fuente || 'other';
  if (src === 'cvr') continue;
  otherCounts[src] = (otherCounts[src] || 0) + 1;
}
const otherLine = Object.entries(otherCounts).map(([k, v]) => `${k}: ${v}`).join(' | ');

// --- Build Telegram message ---
let msg = '\ud83d\udcca *Reporte Diario \u2014 JM Consulting*\n';
msg += `\ud83d\udcc5 ${today.toLocaleDateString('es-AR')}\n\n`;

msg += '\ud83c\udde9\ud83c\uddf0 *CVR Denmark Pipeline*\n';
msg += `Total: ${cvrTotal} leads\n`;
msg += `Con email: ${cvrEmail} (${emailRate}%)\n`;
msg += `Nuevo: ${cvrNuevo} | Emailed: ${cvrEmailed}\n\n`;

if (sectorLines) {
  msg += '\ud83d\udccb *Por sector:*\n' + sectorLines + '\n';
}

msg += '\ud83d\udce7 *WF7 Cold Email Stats*\n';
msg += `Enviados total: ${cvrEmailed} (${sendRate}% del pool)\n`;
msg += `Pendientes de envio: ${cvrConEmailNuevo}\n`;
if (emailedSectorLines) {
  msg += 'Por sector:\n' + emailedSectorLines + '\n';
}
msg += '\n';

msg += `\ud83d\udcca *RAW LEADS total: ${leads.length}*\n`;
if (otherLine) {
  msg += `Otras fuentes: ${otherLine}\n`;
}

msg += '\n\u2705 Pipeline CVR + Cold Email activos.';

return [{ json: { message: msg } }];
